// Mathematical solar irradiance estimation model
export function calculateSolarYield(params: {
  panelCapacityKw: number;
  tiltDegrees: number;
  azimuthDegrees: number;
  annualSunHours: number;
  systemEfficiency: number;
}): { annualKwh: number; monthlyDistribution: number[] } {
  const orientationFactor = Math.cos((params.azimuthDegrees - 180) * (Math.PI / 180)) * 0.15 + 0.85;
  const tiltFactor = Math.cos((params.tiltDegrees - 25) * (Math.PI / 180)) * 0.10 + 0.90;
  const annualKwh = params.panelCapacityKw * params.annualSunHours * params.systemEfficiency * orientationFactor * tiltFactor;
  // Monthly irradiance distribution coefficients
  const weights = [0.06, 0.07, 0.09, 0.10, 0.11, 0.11, 0.10, 0.09, 0.09, 0.08, 0.05, 0.05];
  return { annualKwh: Math.round(annualKwh), monthlyDistribution: weights.map(w => Math.round(annualKwh * w)) };
}

# WebSocket broadcaster and channel routing
from fastapi import FastAPI, WebSocket, WebSocketDisconnect

class ConnectionManager:
    def __init__(self):
        self.active_channels: dict[str, list[WebSocket]] = {}

    async def connect(self, channel: str, websocket: WebSocket):
        await websocket.accept()
        self.active_channels.setdefault(channel, []).append(websocket)

    def disconnect(self, channel: str, websocket: WebSocket):
        if channel in self.active_channels and websocket in self.active_channels[channel]:
            self.active_channels[channel].remove(websocket)

    async def broadcast_alert(self, channel: str, event: dict):
        for connection in self.active_channels.get(channel, []):
            await connection.send_json(event)

